session_start();include('dbstring.php');include('check-login.php');include_once('administration-ops-utils.php');administration_ops_ensure_tables($con);if(!administration_ops_is_lead()){header('location:index.php');exit();}$message='';
if(isset($_POST['update_issue'])){$id=trim((string)$_POST['issueid']);$status=in_array($_POST['status']??'',array('open','in_progress','resolved','closed'),true)?$_POST['status']:'open';$assigned=trim((string)$_POST['assignedto']);$due=trim((string)$_POST['duedate']);$note=trim((string)$_POST['resolutionnote']);$resolved=in_array($status,array('resolved','closed'),true)?date('Y-m-d H:i:s'):null;$stmt=mysqli_prepare($con,'UPDATE tblmaintenanceissue SET status=?,assignedto=?,duedate=?,resolutionnote=?,resolvedat=?,updatedat=NOW() WHERE issueid=?');mysqli_stmt_bind_param($stmt,'ssssss',$status,$assigned,$due,$note,$resolved,$id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$message='Work order updated.';}
$staff=[];$res=mysqli_query($con,"SELECT userid,CONCAT_WS(' ',firstname,othernames,surname) name FROM tblsystemuser WHERE status='active' AND systemtype IN ('Teacher','User') ORDER BY firstname,surname");if($res)while($row=mysqli_fetch_assoc($res))$staff[]=$row;$filter=in_array($_GET['status']??'',array('open','in_progress','resolved','closed'),true)?$_GET['status']:'open';$issues=mysqli_query($con,"SELECT mi.*,CONCAT_WS(' ',su.firstname,su.othernames,su.surname) assignee FROM tblmaintenanceissue mi LEFT JOIN tblsystemuser su ON su.userid=mi.assignedto WHERE mi.status='".mysqli_real_escape_string($con,$filter)."' ORDER BY (mi.duedate IS NULL),mi.duedate ASC,FIELD(mi.priority,'Urgent','High','Normal','Low'),mi.datetimeentry DESC LIMIT 100");$count=['open'=>0,'in_progress'=>0,'resolved'=>0,'closed'=>0];$res=mysqli_query($con,"SELECT status,COUNT(*) total FROM tblmaintenanceissue GROUP BY status");if($res)while($row=mysqli_fetch_assoc($res))$count[$row['status']]=(int)$row['total'];
?>
<!doctype html><html><head><?php include('title.php');include('links.php');?><link rel="stylesheet" href="css/headmaster-dashboard.css"><link rel="stylesheet" href="css/assistant-admin-ops.css"></head><body class="hm-page aops-page"><div class="header"><?php include('menu.php');?></div><main class="hm-shell"><aside class="hm-sidebar"><div class="hm-sidebar__inner"><?php include('welcome.php');include('menuboard.php');?></div></aside><section class="hm-main"><section class="hm-hero hm-hero--single aops-hero"><div><span class="hm-kicker">Facilities management</span><h1>Maintenance work orders</h1><p>Assign issues, set due dates, track progress, and keep a clear record of completed work.</p><div class="hm-hero__footer"><div class="hm-context"><span><i class="fa fa-wrench"></i> Facilities oversight</span><span><i class="fa fa-tasks"></i> Work-order tracker</span></div><a class="aops-back" href="assistant-head-administration-page.php"><i class="fa fa-arrow-left"></i> Dashboard</a></div></div></section><?php if($message!==''){?><div class="aops-flash"><?php echo administration_ops_escape($message);?></div><?php }?><section class="aops-stats"><div class="aops-stat"><i class="fa fa-folder-open"></i><span>Open<strong><?php echo number_format($count['open']);?></strong></span></div><div class="aops-stat"><i class="fa fa-spinner"></i><span>In progress<strong><?php echo number_format($count['in_progress']);?></strong></span></div><div class="aops-stat"><i class="fa fa-check-circle"></i><span>Resolved<strong><?php echo number_format($count['resolved']);?></strong></span></div></section><section class="aops-panel"><div class="hm-panel__head"><div><span class="hm-section__eyebrow">Work-order register</span><h2><?php echo ucwords(str_replace('_',' ',$filter));?> issues</h2></div><div class="aops-filter"><?php foreach(['open'=>'Open','in_progress'=>'In progress','resolved'=>'Resolved','closed'=>'Closed'] as $key=>$label){?><a class="<?php echo $filter===$key?'is-active':'';?>" href="?status=<?php echo $key;?>"><?php echo $label;?></a><?php }?></div></div><div class="aops-table-wrap"><table class="aops-table"><thead><tr><th>Issue</th><th>Owner / due</th><th>Update work order</th></tr></thead><tbody><?php if($issues&&mysqli_num_rows($issues)>0){while($issue=mysqli_fetch_assoc($issues)){?><tr><td><strong><?php echo administration_ops_escape($issue['title']);?></strong><small><?php echo administration_ops_escape($issue['location']);?> · <?php echo administration_ops_escape($issue['priority']);?> · <?php echo administration_ops_escape($issue['description']);?></small></td><td><?php echo administration_ops_escape($issue['assignee']?:'Unassigned');?><small>Due: <?php echo $issue['duedate']?date('d M Y',strtotime($issue['duedate'])):'Not set';?></small></td><td><form method="post" class="aops-form"><input type="hidden" name="issueid" value="<?php echo administration_ops_escape($issue['issueid']);?>"><div class="aops-inline"><select name="status"><option value="open"<?php echo $issue['status']==='open'?' selected':'';?>>open</option><option value="in_progress"<?php echo $issue['status']==='in_progress'?' selected':'';?>>in progress</option><option value="resolved"<?php echo $issue['status']==='resolved'?' selected':'';?>>resolved</option><option value="closed"<?php echo $issue['status']==='closed'?' selected':'';?>>closed</option></select><select name="assignedto"><option value="">Assign to</option><?php foreach($staff as $person){?><option value="<?php echo administration_ops_escape($person['userid']);?>"<?php echo $issue['assignedto']===$person['userid']?' selected':'';?>><?php echo administration_ops_escape($person['name']);?></option><?php }?></select></div><input type="date" name="duedate" value="<?php echo administration_ops_escape($issue['duedate']);?>"><textarea name="resolutionnote" placeholder="Progress or resolution note"><?php echo administration_ops_escape($issue['resolutionnote']);?></textarea><button class="aops-button" name="update_issue">Save update</button></form></td></tr><?php }}else{?><tr><td colspan="3" class="aops-empty">No issues in this view.</td></tr><?php }?></tbody></table></div></section></section></main></body></html>